// Groups for the Topics page. Tags keep their exact published spelling;
// a tag not listed here still appears, under "More topics".
export const TOPIC_GROUPS = [
  { title: "Boards & hardware", tags: ["STM32", "ESP32", "OrangePi Zero 2W", "EPaper"] },
  { title: "Frameworks & tools", tags: ["Qt", "Flutter", "ROS 2", "GUI", "Gatsby"] },
  { title: "Connectivity", tags: ["Bluetooth LE", "CAN", "Ethernet"] },
  { title: "Systems & subjects", tags: ["Embedded Linux", "Embedded Systems", "Robotics", "Computer Vision"] },
];

export function groupTopics(topics) {
  const byName = new Map(topics.map((topic) => [topic.fieldValue, topic]));
  const listed = new Set();
  const groups = TOPIC_GROUPS.map(({ title, tags }) => ({
    title,
    topics: tags.filter((tag) => byName.has(tag)).map((tag) => {
      listed.add(tag);
      return byName.get(tag);
    }),
  }));
  const rest = topics.filter((topic) => !listed.has(topic.fieldValue));
  if (rest.length) groups.push({ title: "More topics", topics: rest });
  return groups.filter((group) => group.topics.length);
}
