import React from "react";
import { Link, graphql } from "gatsby";
import Layout from "../components/layout/layout";
import { SEO as Seo } from "../components/seo";
import { tagPath } from "../lib/content.cjs";
import { groupTopics } from "../lib/topics";
export default function Tags({ data }) {
  const groups = groupTopics(data.allMdx.group);
  return (
    <Layout>
      <section className="page-intro">
        <h1>Browse the topics.</h1>
        <p>Pick a subject and see what’s on the workbench.</p>
      </section>
      <div className="topic-groups">
        {groups.map((group, index) => (
          <section className="topic-group" key={group.title} aria-labelledby={`topic-group-${index}`}>
            <h2 id={`topic-group-${index}`}>{group.title}</h2>
            <ul className="topic-nav">
              {group.topics.map((topic) => (
                <li key={topic.fieldValue}>
                  <Link className="topic-chip" to={tagPath(topic.fieldValue)}>
                    {topic.fieldValue}
                    <span>
                      {topic.totalCount}
                      <span className="sr-only"> {topic.totalCount === 1 ? "article" : "articles"}</span>
                    </span>
                  </Link>
                </li>
              ))}
            </ul>
          </section>
        ))}
      </div>
    </Layout>
  );
}
export const query = graphql`
  query TopicIndex {
    allMdx {
      group(field: { frontmatter: { tags: SELECT } }) {
        fieldValue
        totalCount
      }
    }
  }
`;
export const Head = () => <Seo title="Topics" pathname="/tags/" />;
